'use strict';
let imageUploading=false;
function showLogo(){const brand=$('.brand');if(!brand||brand.querySelector('.site-logo'))return;const img=document.createElement('img');img.className='site-logo';img.alt='網站 LOGO';img.hidden=true;img.onload=()=>{img.hidden=false;brand.querySelector('.mark')?.remove();};img.src='/api/logo?t='+Date.now();brand.prepend(img);}
async function uploadImage(file,url,limit){if(!file)throw Error('請先選擇圖片');if(file.size>limit*1024*1024)throw Error('圖片限 '+limit+' MB');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('請選擇 JPG、PNG 或 WebP 圖片');const r=await apiFetch(url,{method:'POST',headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file});const d=await r.json();if(!r.ok)throw Error(d.error||'上傳失敗');return d;}
function logoDialog(){modal('上傳 LOGO','<p>支援 JPG、PNG、WebP，限 2 MB。上傳成功後立即顯示。</p><p id="logo-upload-time" class="muted">正在讀取目前 LOGO 時間…</p><label class="field">選擇 LOGO<input id="logo-file" type="file" accept="image/png,image/jpeg,image/webp" required></label>','上傳 LOGO',async()=>{const b=$('#submit-modal'),file=$('#logo-file').files[0];b.disabled=true;imageUploading=true;try{const result=await uploadImage(file,'/api/logo',2);addAudit('新增／更換網站 LOGO',file.name,'管理後台 > LOGO 圖片');persist();$('#modal').close();routeAdmin();toast('LOGO 已更新，上傳時間 '+receiptTime(result.created));}finally{imageUploading=false;b.disabled=false;}});apiFetch('/api/logo?meta=1').then(r=>r.json()).then(d=>{const el=$('#logo-upload-time');if(el)el.textContent=d.exists?'目前 LOGO 上傳時間：'+receiptTime(d.created):'目前尚未上傳 LOGO';}).catch(()=>{const el=$('#logo-upload-time');if(el)el.textContent='目前 LOGO 時間無法讀取';});}
function receiptTime(value){const date=new Date(value);return Number.isNaN(date.getTime())?'時間未記錄':new Intl.DateTimeFormat('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date);}
async function loadReceipts(p,box){try{const r=await apiFetch('/api/receipts?project='+encodeURIComponent(p.id));const d=await r.json();if(!r.ok)throw Error(d.error);box.innerHTML=d.items.length?d.items.map(i=>{const url='/api/receipts?project='+encodeURIComponent(p.id)+'&id='+encodeURIComponent(i.id);return '<a class="receipt-image" href="'+esc(url)+'" target="_blank" rel="noopener"><img loading="lazy" src="'+esc(url)+'" alt="'+esc(i.name)+'"><span>'+esc(i.name)+'</span><small>上傳時間：'+esc(receiptTime(i.created))+'</small><small>點選查看原圖</small></a>';}).join(''):'<p class="muted">尚未上傳收據圖片。</p>';if(d.truncated)box.insertAdjacentHTML('beforeend','<p>目前顯示前 1000 張圖片。</p>');}catch(e){box.textContent=e.message||'圖片載入失敗，請重新展開專案。';}}
function addReceipts(){const p=project(),detail=$('.project-detail');if(!p||!detail||$('#receipt-images'))return;const section=document.createElement('section');section.className='admin-card';section.innerHTML='<h2>廠商收據圖片</h2><p class="muted">每張限 10 MB，支援 JPG、PNG、WebP。圖片儲存在私人雲端，刪除專案後復原仍會保留。</p><label class="field">選擇收據圖片（可多選）<input id="receipt-files" type="file" multiple accept="image/png,image/jpeg,image/webp"></label><button type="button" id="upload-receipts">上傳收據</button><p id="image-status" role="status"></p><div id="receipt-images" class="receipt-gallery">正在載入…</div><small>JSON 備份不包含圖片檔案；點選圖片可開啟原圖另存。</small>';detail.append(section);const box=$('#receipt-images');loadReceipts(p,box);$('#upload-receipts').onclick=async()=>{const input=$('#receipt-files'),files=[...input.files],status=$('#image-status'),button=$('#upload-receipts'),uploaded=[];if(!files.length){status.textContent='請先選擇圖片。';return;}button.disabled=true;input.disabled=true;imageUploading=true;let count=0;try{for(const file of files){status.textContent='正在上傳 '+(count+1)+' / '+files.length+'…';await uploadImage(file,'/api/receipts?project='+encodeURIComponent(p.id),10);uploaded.push(file.name);count++;}input.value='';status.textContent='已上傳 '+count+' 張收據。';}catch(e){status.textContent='已上傳 '+count+' 張；'+e.message+'。其餘圖片請重新選擇後上傳。';}finally{if(uploaded.length){for(const name of uploaded)addAudit('新增照片',name,'庫房管理 > '+p.name+' > 廠商收據圖片',p.id);persist();}button.disabled=false;input.disabled=false;imageUploading=false;await loadReceipts(p,box);}};}
const baseBindRows=bindRows;bindRows=function(){baseBindRows();addReceipts();};
const baseRender=render;render=function(){baseRender();showLogo();};
const baseRenderAdmin=renderAdmin;renderAdmin=function(){baseRenderAdmin();showLogo();const actions=$('.admin-actions');if(actions){const b=document.createElement('button');b.textContent='上傳／更換 LOGO';b.onclick=logoDialog;actions.prepend(b);}};
const baseRenderContent=renderContent;renderContent=function(...args){baseRenderContent(...args);showLogo();};
window.addEventListener('beforeunload',e=>{if(imageUploading){e.preventDefault();e.returnValue='';}});
